parameters.jsCode:
// Keep only posts published since the last daily run, strip the HTML, and cap
// the batch so one busy publishing day cannot run up a large model bill.
const MAX_PER_RUN = 3;
const WINDOW_HOURS = 24;
const MIN_WORDS = 60;

const cutoff = Date.now() - WINDOW_HOURS * 60 * 60 * 1000;
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const raw = r.contentSnippet || r.content || r['content:encoded'] || r.description || '';
  const text = String(raw).replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim();

  const stamp = r.isoDate || r.pubDate || r.published;
  const ts = stamp ? new Date(stamp).getTime() : NaN;
  if (Number.isFinite(ts) && ts < cutoff) continue;

  if (text.split(' ').length < MIN_WORDS) continue;

  out.push({
    json: {
      content: text,
      sourceTitle: String(r.title || 'Untitled post').trim(),
      sourceUrl: String(r.link || r.guid || '').trim(),
      origin: 'feed',
    },
  });
}

return out.slice(0, MAX_PER_RUN);

// Give both entry points one identical shape, and trim very long articles at a
// sentence boundary so a 20,000 word page cannot blow the model context.
const MAX_CHARS = 12000;
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  let content = String(j.content || '').replace(/\s+/g, ' ').trim();
  const wordCount = content ? content.split(' ').length : 0;
  let truncated = false;

  if (content.length > MAX_CHARS) {
    content = content.slice(0, MAX_CHARS);
    const cut = content.lastIndexOf('. ');
    if (cut > MAX_CHARS * 0.6) content = content.slice(0, cut + 1);
    truncated = true;
  }

  const key = String(j.sourceUrl || j.sourceTitle || 'api-request').trim();

  out.push({
    json: {
      draftGroupId: key + ' | ' + new Date().toISOString().slice(0, 10),
      content: content,
      wordCount: wordCount,
      truncated: truncated,
      sourceTitle: String(j.sourceTitle || 'Untitled').trim(),
      sourceUrl: String(j.sourceUrl || '').trim(),
      origin: String(j.origin || 'webhook'),
      startedAt: Date.now(),
    },
  });
}

return out;

// Read the single brand voice row and attach it to every brief. When the tab is
// empty or unreachable, sensible defaults keep the workflow running.
const row = $input.first() ? ($input.first().json || {}) : {};

function pick(keys, fallback) {
  for (const k of keys) {
    const v = row[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return fallback;
}

function list(value) {
  return String(value || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean);
}

const voice = {
  brandName: pick(['Brand Name', 'brandName'], 'the brand'),
  audience: pick(['Audience', 'audience'], 'a general business audience'),
  tone: pick(['Tone', 'tone'], 'clear, plain and useful'),
  callToAction: pick(['Call To Action', 'CTA', 'cta'], 'Read the full post'),
  hashtags: list(pick(['Hashtags', 'hashtags'], '')),
  bannedWords: list(pick(['Banned Words', 'bannedWords'], '')),
  maxHashtags: Number(pick(['Max Hashtags', 'maxHashtags'], '5')) || 5,
};

return $('Prepare Brief').all().map(function (i) {
  return { json: Object.assign({}, i.json, { voice: voice }) };
});

