// Channel limits are a hard requirement, not a suggestion, so they are applied
// in code rather than trusted to the model. Anything over length is repaired
// and the repair is recorded, so a reviewer can see what the model got wrong.
const LIMITS = { tweet: 280, linkedin: 3000, instagram: 2200, newsletter: 900, summary: 600 };

function clean(text, banned) {
  let t = String(text || '').replace(/\r/g, '').trim();
  for (const word of banned) {
    if (!word) continue;
    t = t.replace(new RegExp('\\b' + word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'gi'), '').replace(/\s{2,}/g, ' ');
  }
  return t.trim();
}

function trim(text, limit) {
  if (text.length <= limit) return { text: text, repaired: false };
  let cut = text.slice(0, limit);
  const stop = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('\n'));
  if (stop > limit * 0.6) cut = cut.slice(0, stop + 1);
  return { text: cut.trim(), repaired: true };
}

function splitTweet(text, limit) {
  const parts = [];
  let rest = String(text || '').trim();
  while (rest.length > limit) {
    let cut = rest.slice(0, limit);
    const stop = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf(', '), cut.lastIndexOf(' '));
    if (stop > limit * 0.5) cut = rest.slice(0, stop + 1);
    parts.push(cut.trim());
    rest = rest.slice(cut.length).trim();
  }
  if (rest) parts.push(rest);
  return parts;
}

const out = [];

for (const item of $input.all()) {
  const brief = $('Apply Brand Voice').all()[out.length];
  const source = brief ? brief.json : {};
  const voice = source.voice || { bannedWords: [], hashtags: [], maxHashtags: 5 };
  const banned = voice.bannedWords || [];
  const draft = item.json.output || {};
  const repairs = [];

  // Hashtags: dedupe, force a leading hash, and respect the brand cap.
  const tags = [];
  for (const t of [].concat(draft.hashtags || [], voice.hashtags || [])) {
    const tag = String(t || '').trim().replace(/^#*/, '');
    if (!tag) continue;
    const full = '#' + tag;
    if (!tags.some(function (x) { return x.toLowerCase() === full.toLowerCase(); })) tags.push(full);
  }
  if (tags.length > voice.maxHashtags) {
    repairs.push('Trimmed hashtags from ' + tags.length + ' to ' + voice.maxHashtags);
    tags.length = voice.maxHashtags;
  }

  // Thread: every tweet is forced under the character limit.
  const thread = [];
  for (const t of (Array.isArray(draft.tweetThread) ? draft.tweetThread : [])) {
    const body = clean(t, banned);
    if (!body) continue;
    if (body.length > LIMITS.tweet) {
      const pieces = splitTweet(body, LIMITS.tweet);
      repairs.push('Split one tweet of ' + body.length + ' characters into ' + pieces.length + ' parts');
      pieces.forEach(function (p) { thread.push(p); });
    } else {
      thread.push(body);
    }
  }

  const li = trim(clean(draft.linkedinPost, banned), LIMITS.linkedin);
  if (li.repaired) repairs.push('Shortened the LinkedIn post to ' + LIMITS.linkedin + ' characters');

  const ig = trim(clean(draft.instagramCaption, banned), LIMITS.instagram);
  if (ig.repaired) repairs.push('Shortened the Instagram caption to ' + LIMITS.instagram + ' characters');

  const nl = trim(clean(draft.newsletterBlurb, banned), LIMITS.newsletter);
  if (nl.repaired) repairs.push('Shortened the newsletter blurb to ' + LIMITS.newsletter + ' characters');

  const summary = trim(clean(draft.summary, banned), LIMITS.summary).text;

  out.push({
    json: {
      draftGroupId: source.draftGroupId || '',
      sourceTitle: source.sourceTitle || '',
      sourceUrl: source.sourceUrl || '',
      origin: source.origin || 'webhook',
      wordCount: source.wordCount || 0,
      truncated: !!source.truncated,
      startedAt: source.startedAt || Date.now(),
      brandName: voice.brandName,
      callToAction: voice.callToAction,
      summary: summary,
      keyPoints: (Array.isArray(draft.keyPoints) ? draft.keyPoints : []).map(function (k) { return clean(k, banned); }).filter(Boolean),
      hookVariants: (Array.isArray(draft.hookVariants) ? draft.hookVariants : []).map(function (k) { return clean(k, banned); }).filter(Boolean),
      tweetThread: thread,
      linkedinPost: li.text,
      instagramCaption: ig.text,
      newsletterBlurb: nl.text,
      hashtags: tags,
      repairs: repairs,
    },
  });
}

return out;

// One row per channel, so the queue tab reads like an editorial calendar and a
// human can approve or reject each draft on its own.
const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const tags = (d.hashtags || []).join(' ');

  const channels = [
    { channel: 'Summary', body: d.summary },
    { channel: 'Key points', body: (d.keyPoints || []).map(function (k) { return '- ' + k; }).join('\n') },
    { channel: 'Hook options', body: (d.hookVariants || []).map(function (k, i) { return (i + 1) + '. ' + k; }).join('\n') },
    { channel: 'X thread', body: (d.tweetThread || []).map(function (t, i) { return (i + 1) + '/' + d.tweetThread.length + ' ' + t; }).join('\n\n') },
    { channel: 'LinkedIn', body: d.linkedinPost },
    { channel: 'Instagram', body: [d.instagramCaption, tags].filter(Boolean).join('\n\n') },
    { channel: 'Newsletter', body: d.newsletterBlurb },
  ];

  for (const c of channels) {
    if (!c.body) continue;
    out.push({
      json: {
        draftId: d.draftGroupId + ' | ' + c.channel,
        draftGroupId: d.draftGroupId,
        channel: c.channel,
        body: c.body,
        characters: c.body.length,
        sourceTitle: d.sourceTitle,
        sourceUrl: d.sourceUrl,
        status: 'Needs review',
        createdAt: new Date().toISOString(),
      },
    });
  }
}

return out;

// Collapse the run into one item, so the caller gets a single JSON response and
// Slack gets a single message no matter how many articles were processed.
const drafts = $('Enforce Channel Limits').all().map(function (i) { return i.json; });
const rows = $('Split Into Channel Rows').all().map(function (i) { return i.json; });

const first = drafts[0] || {};
const repairs = [];
drafts.forEach(function (d) { (d.repairs || []).forEach(function (r) { repairs.push(d.sourceTitle + ': ' + r); }); });

const lines = ['*Content repurposed*'];
drafts.forEach(function (d) {
  lines.push('- ' + (d.sourceTitle || 'Untitled') + ' (' + d.wordCount + ' words' +
    (d.truncated ? ', trimmed for length' : '') + ') into ' +
    rows.filter(function (r) { return r.draftGroupId === d.draftGroupId; }).length + ' drafts');
});
lines.push('');
lines.push('Total drafts queued: ' + rows.length + '  |  Waiting in the queue tab as Needs review');
if (repairs.length) {
  lines.push('');
  lines.push('*Automatic fixes applied*');
  repairs.slice(0, 8).forEach(function (r) { lines.push('- ' + r); });
  if (repairs.length > 8) lines.push('- and ' + (repairs.length - 8) + ' more');
}

return [{
  json: {
    origin: first.origin || 'webhook',
    slackText: lines.join('\n'),
    payload: {
      sourcesProcessed: drafts.length,
      draftsQueued: rows.length,
      automaticFixes: repairs,
      drafts: drafts.map(function (d) {
        return {
          sourceTitle: d.sourceTitle,
          sourceUrl: d.sourceUrl,
          brandName: d.brandName,
          callToAction: d.callToAction,
          summary: d.summary,
          keyPoints: d.keyPoints,
          hookVariants: d.hookVariants,
          tweetThread: d.tweetThread,
          linkedinPost: d.linkedinPost,
          instagramCaption: d.instagramCaption,
          newsletterBlurb: d.newsletterBlurb,
          hashtags: d.hashtags,
          sourceWordCount: d.wordCount,
          sourceTrimmed: d.truncated,
        };
      }),
      latencyMs: Date.now() - (Number(first.startedAt) || Date.now()),
    },
  },
}];
